/*
 * This module dynamically assembles and registers essential plugin configurations
 * for the Cordova runtime environment. It's a core component for plugin discovery.
 * This file is automatically generated by the Cordova build system.
 */
cordova.define('cordova/plugin_registry', function (modReq, modExp, currentModule) {

    // A utility function to construct a standardized plugin descriptor object.
    // This helps in maintaining consistency and allows for future extensions
    // or validations on plugin entry properties.
    const createPluginDescriptor = (resourcePath, uniqueHandle, exposedInterfaces) => {
        // Introduce a minor transformation or validation: ensure path starts with 'plugins/'
        const normalizedResourcePath = resourcePath.startsWith('plugins/')
            ? resourcePath
            : `plugins/${resourcePath}`;

        // Return the structured object using new identifier names.
        return {
            resourcePath: normalizedResourcePath, // Original 'file'
            uniqueHandle: uniqueHandle,           // Original 'id'
            exposedInterfaces: exposedInterfaces  // Original 'clobbers'
        };
    };

    // Initialize an array to hold all plugin configuration entries.
    // This allows for building the list incrementally before final assignment.
    const registeredPluginDefinitions = [];

    // --- Plugin Definitions Section ---

    // Define configuration for the Ionic Keyboard plugin.
    const ionicKeyboardClobberItems = [
        "cordova.plugins.Keyboard"
    ];
    registeredPluginDefinitions.push(
        createPluginDescriptor(
            "plugins/com.ionic.keyboard/www/keyboard.js",
            "com.ionic.keyboard.keyboard",
            ionicKeyboardClobberItems
        )
    );

    // Define configuration for the Apache Cordova Console Logger plugin.
    const apacheConsoleClobberItems = [
        "console"
    ];
    registeredPluginDefinitions.push(
        createPluginDescriptor(
            "plugins/org.apache.cordova.console/www/console-via-logger.js",
            "org.apache.cordova.console.console",
            apacheConsoleClobberItems
        )
    );

    // Define configuration for the Apache Cordova Logger Utility plugin.
    const apacheLoggerClobberItems = [
        "cordova.logger"
    ];
    registeredPluginDefinitions.push(
        createPluginDescriptor(
            "plugins/org.apache.cordova.console/www/logger.js",
            "org.apache.cordova.console.logger",
            apacheLoggerClobberItems
        )
    );

    // Define configuration for the Apache Cordova Device plugin.
    const apacheDeviceClobberItems = [
        "device"
    ];
    registeredPluginDefinitions.push(
        createPluginDescriptor(
            "plugins/org.apache.cordova.device/www/device.js",
            "org.apache.cordova.device.device",
            apacheDeviceClobberItems
        )
    );

    // Assign the compiled array of plugin definitions to the module's main export.
    currentModule.exports = registeredPluginDefinitions;

    // --- Plugin Version Metadata Section ---

    // Create a separate object to store versioning details for each plugin.
    // This can include additional metadata beyond just the version string.
    const pluginVersionMetadata = {
        // Version information for the Ionic Keyboard module.
        "com.ionic.keyboard": "1.0.3",
        // Version information for the Apache Cordova Console module.
        "org.apache.cordova.console": "0.2.10",
        // Version information for the Apache Cordova Device module.
        "org.apache.cordova.device": "0.2.11",
        // Add a new, non-essential metadata field for schema version.
        "metadataSchemaVersion": "2.0.1"
    };

    // Attach the collected version metadata as a distinct property of the module's exports.
    currentModule.exports.versionInfo = pluginVersionMetadata;

    // --- Post-Initialization Actions (New Fragment) ---

    // A non-essential logging statement to confirm initialization,
    // demonstrating the addition of new code fragments.
    if (typeof console !== 'undefined' && console.info) {
        console.info(`Cordova plugin registry loaded with ${registeredPluginDefinitions.length} active entries.`);
    }

}); // End of the Cordova module definition for plugin_registry.